<?php /** Scrolling motivational ticker from quotes.json. Expects $phrases. Duration scales with count so it stays readable. */ ?>
<div class="ticker" aria-hidden="true"><div class="ticker-track" style="animation-duration:<?= max(30, count($phrases) * 5) ?>s"><?php for ($repeat = 0; $repeat < 2; $repeat++): foreach ($phrases as $phrase): ?><span class="ticker-dot">&#9670;</span><span class="ticker-phrase"><?= escapeHtml($phrase) ?></span><?php endforeach; endfor; ?></div></div>
